import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第六章","description":"《正易心法》第六章——消息卦画，无止于辞：卦辞只是卦义的粗略截面，须于辞外见意，方审《易》道。","frontmatter":{"title":"正易心法·第六章","description":"《正易心法》第六章——消息卦画，无止于辞：卦辞只是卦义的粗略截面，须于辞外见意，方审《易》道。","category":"guide","aliases":["正易心法第六章","消息卦画无止于辞","辞外见意"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-06.md","filePath":"yijing/zheng-yi-xin-fa/chapter-06.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-06.md"},f=d({...c,setup(u){const o=[{id:"z6-01",label:"一、无止于辞",showLabel:!0,sentences:[["消息卦画，无止于辞。",{text:"辞外见意",glossary:"ciwaiJianyi"},"，方",{text:"审",glossary:"shen"},"《易》道。"]],note:["卦画中阴阳消息的道理，不止步于文辞；能在文辞之外看到意涵，才算真正明察《易》道。（这是第六章的总纲，也是前五章理论的第一次方法论示范。）"]},{id:"z6-02",label:"二、特系大略之辞",showLabel:!0,sentences:[["系辞，特系以吉凶",{text:"大略之辞",glossary:"dalueZhici"},"而已，非谓六画之义尽于是也。"]],note:["系在卦上的文辞，只不过是对吉凶的粗略概括，并非说六爻卦画的全部意义就尽于此。（「特」是只、不过；「系辞」在这里指系在卦爻下的辞，不是篇名。）"]},{id:"z6-03",label:"三、数字岂能尽义",showLabel:!0,sentences:[["如大有系以元亨，大壮系以利贞。此数字，果足以尽二卦之义乎？"]],note:["比如大有卦只系了「元亨」两字，大壮卦只系了「利贞」两字——这几个字，真的足以穷尽这两卦的全部意义吗？（大有是上离下乾「日在天上」，大壮是上震下乾「雷在天上」，卦画结构完全不同，处境与警示也截然不同，而卦辞都只有两个字。）"]},{id:"z6-04",label:"四、辞外之意",showLabel:!0,sentences:[["要须辞外见意可也。辞外之意，如乾九二“见龙在田”，上九“亢龙有悔”，"]],note:["必须要在文辞之外看到意涵才行。辞外之意，比如乾卦九二「见龙在田」、上九「亢龙有悔」——辞说的是「龙出现在田野」「飞得太高的龙会后悔」，象说的是阳气从地下升至地面、阳极必阴的消息铁律，不是一个关于龙的故事，也不是道德劝诫。"]},{id:"z6-05",label:"五、辟师之喻",showLabel:!0,sentences:[["辟师之上不动如地，内趋变如水，"]],note:["又如师卦：上卦坤不动如大地，下卦坎内趋变动如流水。（师卦䷆上坤下坎——辟（君主）居上如地载物，师（军队）居下如水无常形。外静内动，正是用兵之道的最高境界；这也是《孙子兵法》「动如雷霆，静如山岳」的易学根源。）"]},{id:"z6-06",label:"六、辞所不能该",showLabel:!0,sentences:[["无穷好意，如此类不可概举，皆是辞之所不能",{text:"该",glossary:"gai"},"也。"]],note:["这些无穷的妙义，此类例子不可一一列举，都是文辞所不能完全涵盖的。（「该」通「赅」，完备涵盖。辞是卦义的截面，卦画是卦义的全体——就像用一张照片描述一个人：照片能捕捉某一瞬间，但人的全部生命不在照片里。）"]}],i=[{id:"ciwaiJianyi",term:"辞外见意",pinyin:"cí wài jiàn yì",meaning:"在文辞之外看到意涵。超越文字，直观卦画深意。"},{id:"shen",term:"审",pinyin:"shěn",meaning:"细察、明辨。「方审《易》道」即才能真正明察《易》道。"},{id:"dalueZhici",term:"大略之辞",pinyin:"dà lüè zhī cí",meaning:"粗略概括的文字。辞只是大概，非全义。"},{id:"gai",term:"该",pinyin:"gāi",meaning:"涵盖、包括。古义「该」通「赅」，完备涵盖。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e("",19)),s(r,{colophon:"无止于辞 · 辞外见意 · 大略之辞 · 外静内动",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第六章原文",sections:o,glossary:i}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如「易曰」作「易曰」、「该」通「赅」），不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"辞外见意",pinyin:["cí","wài"],meaning:"在文辞之外看到意涵。超越文字，直观卦画深意——本章的方法论核心。"},{term:"大略之辞",pinyin:["dà","lüè"],meaning:"粗略概括的文字。辞只是大概，非全义。"},{term:"大有 · 大壮",pinyin:["dà","yǒu"],meaning:"大有䷍（上离下乾，日在天上）辞「元亨」；大壮䷡（上震下乾，雷在天上）辞「利贞」。结构迥异而辞皆两字。"},{term:"辟师",pinyin:["pì","shī"],meaning:"辟为君主，师为军队。师卦上坤下坎：上不动如地，内趋变如水——外静内动，用兵之极。"},{term:"该",pinyin:["gāi"],meaning:"通「赅」，完备涵盖。「辞之所不能该」即文辞不能完全涵盖。"}]}),t[3]||(t[3]=e("",23))])}}});export{y as __pageData,f as default};
